void maxHeapify(int A[], int n, int i) {
    int largest = i, l = 2*i, r = 2*i + 1;
    if (l <= n && A[l] > A[largest]) largest = l;
    if (r <= n && A[r] > A[largest]) largest = r;
    if (largest != i) {
        swap(&A[i], &A[largest]);
        maxHeapify(A, n, largest);
    }
}

void buildMaxHeap(int A[], int n) {
    for (int i = n / 2; i >= 1; i--)
